# Code generated by Claude
"""
The follower in the simulator: the whole staging (ARMS, PEDESTAL, DRIVE, CREEP_IN, NECK) with NAV_CFG["follow"] off (today's scripted DRIVE) and on (the navigation core plans, the follower drives), side by side:
the arrival error at the approach spot, the pose error at the handoff, the DRIVE time, the base's peak lean, the clearance to the bench, the route and planning time. One simulation at a time.

    MUJOCO_GL=egl python experiments/nav_follow_sim_test.py [--only on|off]

Pass: with it on the episode reaches the handoff, the arrival at the approach spot is within 1 cm and 1 degree, the handoff pose error is within 1 cm and 1 degree, the lean stays under the 1 degree bound, no replan
was needed and the route did not leave its 5 cm band; the arrival error of both runs is printed whatever the result.
"""

import argparse
import contextlib
import io
import os
import sys
import time
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import gc  # noqa: E402

from src.episode_runner import run_episode  # noqa: E402
from src.task_beaker_hotplate import load_task, make_task  # noqa: E402
from src.task_config import NAV_CFG  # noqa: E402

results = []


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}" + (f"  {detail}" if detail else ""), flush=True)


def staging_run(follow):
    NAV_CFG["follow"] = follow
    try:
        sim = load_task(cameras=True)
        task = make_task(None)
        t0 = time.time()
        with contextlib.redirect_stdout(io.StringIO()):
            s = run_episode(task, sim.model, sim.data, stop_after_handoff_s=0.5)
        s["_wall_s"] = time.time() - t0
        return s
    finally:
        NAV_CFG["follow"] = False
        gc.collect()


def show(tag, s):
    a, h = s["arrival_at_end_of_drive"], s["base_pose_error_at_handoff"]
    if a is None or h is None:
        print(f"  [{tag}] outcome {s['outcome']}: {s.get('staging_error')}", flush=True)
        return
    print(f"  [{tag}] outcome {s['outcome']}; DRIVE {s['phase_durations_s'].get('DRIVE', float('nan')):.1f} s, CREEP_IN {s['phase_durations_s'].get('CREEP_IN', float('nan')):.1f} s; "
          f"arrival at the approach spot {a['pos_err_mm']:.1f} mm, {abs(a['yaw_err_deg']):.2f} deg; handoff pose error {h['pos_err_mm']:.1f} mm, {abs(h['yaw_err_deg']):.2f} deg; "
          f"peak lean DRIVE {s['max_base_lean_deg_by_phase'].get('DRIVE', float('nan')):.2f} deg; min clearance to the bench {s['min_base_to_bench_clearance_during_drive_mm']:.0f} mm; wall {s['_wall_s']:.0f} s", flush=True)


def main(only):
    out = {}
    for tag, follow in (("off", False), ("on", True)):
        if only and only != tag:
            continue
        print(f"\nstaging with follow {tag}", flush=True)
        out[tag] = staging_run(follow)
        show(tag, out[tag])
    if "on" in out:
        s = out["on"]
        nav = s.get("nav") or {}
        r0 = (nav.get("routes") or [{}])[0]
        print(f"  route: length {r0.get('length', float('nan')):.2f} m, lead-in {r0.get('lead_in_m')}, lead-out {r0.get('lead_out_m')}, smoothed {r0.get('smoothed')}, max curvature {r0.get('max_curvature', float('nan')):.2f} 1/m; "
              f"curvature used {nav.get('max_curvature_used', float('nan')):.2f}; build {nav.get('build_seconds', float('nan')):.1f} s, planning {nav.get('plan_seconds', float('nan')):.2f} s; footprint {nav.get('footprint')}")
        a, h = s["arrival_at_end_of_drive"], s["base_pose_error_at_handoff"]
        check("follow on: the episode reaches the handoff", s["outcome"] == "STAGING_COMPLETE", f"{s['outcome']} {s.get('staging_error')}")
        check("the arrival at the approach spot is within 1 cm and 1 degree", a is not None and a["pos_err_mm"] <= 10.0 and abs(a["yaw_err_deg"]) <= 1.0, f"{a}")
        check("the handoff pose error is within 1 cm and 1 degree", h is not None and h["pos_err_mm"] <= 10.0 and abs(h["yaw_err_deg"]) <= 1.0, f"{h}")
        check("the peak lean in the DRIVE stays under 1 degree", s["max_base_lean_deg_by_phase"].get("DRIVE", 99.0) < 1.0)
        check("no replan, and the route stayed within its 5 cm band", nav.get("replans") == 0 and nav.get("cross_track_max_mm", 99999) < 50.0, f"replans {nav.get('replans')}, cross-track {nav.get('cross_track_max_mm', float('nan')):.1f} mm")
    print(f"\n{sum(results)}/{len(results)} checks passed")
    return all(results)


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--only", choices=("on", "off"))
    sys.exit(0 if main(ap.parse_args().only) else 1)
